CREATE TABLE game_player(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,coins BIGINT NOT NULL DEFAULT 0,pos_x DOUBLE NOT NULL,pos_y DOUBLE NOT NULL,pos_z DOUBLE NOT NULL,yaw DOUBLE NOT NULL DEFAULT 0,hat VARCHAR(40) NULL,outfit VARCHAR(40) NULL,cleared_time DATETIME NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user(user_id),CONSTRAINT ck_coins CHECK (coins >= 0));
CREATE TABLE game_pickup(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,spot_id VARCHAR(40) NOT NULL,period VARCHAR(10) NOT NULL,amount INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user_spot_period(user_id,spot_id,period),INDEX idx_user_period(user_id,period));
CREATE TABLE game_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,item_id VARCHAR(40) NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user_item(user_id,item_id));
CREATE TABLE game_coin_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,kind VARCHAR(20) NOT NULL,ref VARCHAR(40) NOT NULL,amount INT NOT NULL,balance_after BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,INDEX idx_user_id(user_id,id));
